import threading

import psycopg


def reproduce(connect, service) -> str | None:
    account_id = 1
    amount = 3000
    n_threads = 16
    barrier = threading.Barrier(n_threads)
    errors = []
    errors_lock = threading.Lock()

    def worker():
        try:
            with connect() as conn:
                barrier.wait(timeout=10)
                try:
                    service.withdraw(conn, account_id, amount)
                except service.DailyLimitExceeded:
                    pass
                except psycopg.errors.Error:
                    # Expected possible DB rejection (e.g. balance check);
                    # the final DB state below decides whether the rule broke.
                    pass
        except Exception as exc:  # barrier / connection setup issues
            with errors_lock:
                errors.append(exc)

    threads = [threading.Thread(target=worker) for _ in range(n_threads)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=20)

    if any(t.is_alive() for t in threads):
        return None

    with connect() as conn:
        (total,) = conn.execute(
            "SELECT COALESCE(SUM(amount), 0) FROM withdrawals "
            "WHERE account_id = %s AND day = current_date",
            (account_id,),
        ).fetchone()

    limit = getattr(service, "DAILY_LIMIT", 5000)
    if total > limit:
        return (
            f"daily limit broken: account {account_id} withdrew {total} "
            f"today, above the daily limit of {limit}"
        )
    return None
